/**
 * 文章描述（摘要）助手
 * ------------------------------------------------------------
 * 提供 article_add / article_edit 两个页面共用的功能：
 *   1. stripHTMLTags(html)                           —— 健壮去除 HTML 标签 / HTML 实体 / Markdown 残留
 *   2. generateDescriptionFromContent(length)        —— 从正文生成一段纯文本摘要
 *   3. autoGenerateDescription()                     —— 带二次确认，写入 #description 输入框
 *   4. updateDescriptionCounter()                    —— 字符计数（上限 200，超限红色）
 *   5. showDescriptionConfirm(message, preview, cb)  —— 自定义二次确认弹窗（替代原生 confirm()）
 *
 * 设计原则：
 *   - 不依赖任何外部库（无 jQuery），单文件即可使用；
 *   - 通过 window.ArticleDescriptionHelper 暴露给模板 onclick 使用；
 *   - 支持"编辑器协议"：若 document 上派发出 editor:register 事件并提供
 *     api.getText()，则优先从编辑器读取纯文本，否则兜底读取 #content textarea。
 */
(function (global) {
    'use strict';

    // ==================================================================
    // 1. 公共工具：健壮的 HTML 去除
    // ==================================================================

    /**
     * 使用浏览器 DOM 解析 HTML，尽可能可靠地拿到纯文本。
     * - 用 DOMParser 解析（避免 innerHTML，降低脚本注入风险）；
     * - 先移除 <script>/<style>/<noscript> 等块及其内容；
     * - 用 document.body.textContent 读取，天然处理 &nbsp;、&amp;、&#123; 等实体；
     * - 对 Markdown 的 **粗体**、# 标题、[链接](url)、`代码`、- 列表
     *   等常见装饰符号做二次清洗；
     * - 合并多余空行 / 空白；
     * - 最后 trim。
     *
     * 解析失败时走正则兜底：剥标签 + 解码常见实体。
     *
     * @param {string} html
     * @returns {string}
     */
    function stripHTMLTags(html) {
        if (typeof html !== 'string') return '';
        if (!html) return '';

        // 快速路径：完全没有 < 的内容，直接做一次 Markdown 清洗
        if (html.indexOf('<') === -1) {
            return cleanupPlainText(html);
        }

        var plain = '';

        // 优先使用浏览器原生 DOMParser
        if (global.DOMParser) {
            try {
                var parser = new global.DOMParser();
                var doc = parser.parseFromString(html, 'text/html');

                // 移除 script / style / noscript
                var toxicTags = ['script', 'style', 'noscript'];
                for (var i = 0; i < toxicTags.length; i++) {
                    var nodes = doc.querySelectorAll(toxicTags[i]);
                    for (var j = 0; j < nodes.length; j++) {
                        if (nodes[j] && nodes[j].parentNode) {
                            nodes[j].parentNode.removeChild(nodes[j]);
                        }
                    }
                }

                plain = doc.body ? (doc.body.textContent || doc.body.innerText || '') : '';
            } catch (e) {
                plain = '';
            }
        }

        // DOMParser 失败时的兜底：正则去除 + 实体解码
        if (!plain) {
            plain = html
                .replace(/<script[\s\S]*?<\/script>/gi, '')
                .replace(/<style[\s\S]*?<\/style>/gi, '')
                .replace(/<noscript[\s\S]*?<\/noscript>/gi, '')
                .replace(/<!--[\s\S]*?-->/g, '')
                .replace(/<\/?[^>]+>/g, ' ')
                .replace(/&nbsp;/gi, ' ')
                .replace(/&amp;/gi, '&')
                .replace(/&lt;/gi, '<')
                .replace(/&gt;/gi, '>')
                .replace(/&quot;/gi, '"')
                .replace(/&#39;/gi, "'")
                .replace(/&#(\d+);/g, function (m, num) {
                    try { return String.fromCharCode(parseInt(num, 10)); } catch (e) { return ''; }
                })
                .replace(/&#x([0-9a-f]+);/gi, function (m, hex) {
                    try { return String.fromCharCode(parseInt(hex, 16)); } catch (e) { return ''; }
                });
        }

        return cleanupPlainText(plain);
    }

    /**
     * 对纯文本做 Markdown 符号与空白的二次清洗。
     */
    function cleanupPlainText(text) {
        if (!text) return '';

        return text
            // 合并所有空白（包括全角空格 / tab / 换行）为单一空格
            .replace(/[\s\u3000]+/g, ' ')
            // 去掉 Markdown 常见的装饰符号（**粗体**、#标题、`代码`、> 引用、- 列表）
            .replace(/[#*_`>~\-]/g, ' ')
            // 去掉 [text](url) 的 (url) 部分，保留 text
            .replace(/\([^)]*\)\s*\{[^}]*\}/g, '')
            .replace(/\([^)]*\)/g, '')
            // 去掉 ![alt](url) 中残留的 ![]
            .replace(/!\[[^\]]*\]/g, '')
            .replace(/\[[^\]]*\]/g, '')
            // 合并清洗过程中产生的多余空格
            .replace(/\s+/g, ' ')
            .trim();
    }

    // ==================================================================
    // 2. 正文读取：兼容编辑器协议
    // ==================================================================

    // 当前已注册的编辑器 API（与 article_edit.html 中字数统计的
    // registeredApi 保持同样的协议，互不冲突）。
    var registeredApi = null;

    if (global.addEventListener) {
        global.addEventListener('editor:register', function (evt) {
            if (evt && evt.detail && evt.detail.api) {
                registeredApi = evt.detail.api;
            }
        }, false);
    }

    function getContentPlainText() {
        // 1) 优先从已注册的编辑器取纯文本
        if (registeredApi && typeof registeredApi.getText === 'function') {
            try {
                var t = registeredApi.getText();
                if (t) return t;
            } catch (e) { /* 忽略编辑器异常，继续兜底 */ }
        }

        // 2) 兜底：直接读取 textarea
        var textarea = document.getElementById('content');
        if (textarea) return textarea.value || '';
        return '';
    }

    // ==================================================================
    // 3. 描述生成
    // ==================================================================

    /**
     * 从正文生成一段纯文本摘要。
     * @param {number} length 默认 200
     * @returns {string}
     */
    function generateDescriptionFromContent(length) {
        length = typeof length === 'number' && length > 0 ? length : 200;

        var plain = stripHTMLTags(getContentPlainText());

        if (!plain) return '';

        if (plain.length > length) {
            return plain.substring(0, length) + '';
        }
        return plain;
    }

    // ==================================================================
    // 4. 字符计数（与 <span id="description-counter"> 配合）
    // ==================================================================

    function updateDescriptionCounter() {
        var descInput = document.getElementById('description');
        var counter = document.getElementById('description-counter');
        if (!descInput || !counter) return;

        var len = (descInput.value || '').length;
        counter.textContent = len + '/200';
        counter.style.color = len > 200 ? '#e74c3c' : '#888';
    }

    // ==================================================================
    // 5. 自定义二次确认弹窗（替代原生 window.confirm()）
    // ==================================================================
    //
    // 好处：
    //   - 样式与后台整体 UI 一致（按钮色、圆角、遮罩）；
    //   - 可自定义标题、正文、按钮文案；
    //   - 可在弹窗内展示「将被替换为」的内容预览；
    //   - 不被浏览器强制禁用；
    //   - 文案可独立做本地化（虽然当前是写死中文，但结构已抽离）。

    // 单例说明：弹窗外壳（遮罩/标题栏/按钮）不再自建，统一复用 common.js 的
    // showConfirmDialog（components.css 的 .modal-overlay > .confirm-dialog 体系，
    // 自带暗色主题适配），此处只负责组装文案与回调。

    /**
     * 显示一个自定义的二次确认弹窗（基于统一确认弹窗 showConfirmDialog 实现）。
     *
     * @param {{title?:string, message:string, preview?:string, confirmText?:string, cancelText?:string, onConfirm?:()=>void, onCancel?:()=>void}} options
     */
    function showDescriptionConfirm(options) {
        if (!options || typeof options.message !== 'string') {
            throw new Error('showDescriptionConfirm: options.message is required');
        }

        // 组装消息文本：正文 + 预览块（showConfirmDialog 默认做 HTML 转义并把 \n 转 <br>）
        var message = options.message;
        if (typeof options.preview === 'string' && options.preview.length > 0) {
            message += '\n【将被替换为】\n' + options.preview;
        }

        return showConfirmDialog(message, {
            title: options.title || '提示',
            type: 'info',
            confirmText: options.confirmText || '确认',
            // cancelText 传空字符串时统一弹窗不渲染「取消」按钮，即变成纯提示（alert 样式）
            cancelText: options.cancelText !== undefined ? options.cancelText : '取消'
        }).then(function (confirmed) {
            if (confirmed) {
                if (typeof options.onConfirm === 'function') options.onConfirm();
            } else {
                if (typeof options.onCancel === 'function') options.onCancel();
            }
            return confirmed;
        });
    }

    // ==================================================================
    // 6. 主入口：自动生成（带二次确认）
    // ==================================================================

    /**
     * 点击「自动生成」按钮时调用。
     *
     * 流程：
     *   1. 若正文为空 → 弹一个简单提示，不覆盖现有描述；
     *   2. 若描述框已有内容 → 弹自定义 modal 二次确认；
     *   3. 其它情况 → 直接写入；
     *   4. 最后刷新字符计数。
     */
    function autoGenerateDescription() {
        var descEl = document.getElementById('description');
        if (!descEl) return;

        var existing = (descEl.value || '').trim();
        var generated = generateDescriptionFromContent(200);

        // 正文为空：给一个友好提示，不覆盖已有描述（cancelText 传空 = 只显示「知道了」单按钮）
        if (!generated) {
            showDescriptionConfirm({
                title: '无法生成描述',
                message: '当前正文内容为空，无法自动生成描述。请先填写正文后再试。',
                confirmText: '知道了',
                cancelText: '',
                onConfirm: function () { /* 仅关闭 */ }
            });
            return;
        }

        // 描述框已有内容：二次确认（带预览）
        if (existing && existing !== generated) {
            showDescriptionConfirm({
                title: '覆盖已有描述？',
                message: '描述框中已有内容，是否用从正文自动生成的内容覆盖？',
                preview: generated,
                confirmText: '覆盖',
                cancelText: '保留原样',
                onConfirm: function () {
                    descEl.value = generated;
                    updateDescriptionCounter();
                }
                // onCancel 不写，默认什么都不做
            });
            return;
        }

        // 描述框为空：直接写入
        descEl.value = generated;
        updateDescriptionCounter();
    }

    // ==================================================================
    // 7. 暴露到全局（模板 onclick 可直接调用）
    // ==================================================================

    var api = {
        stripHTMLTags: stripHTMLTags,
        generateDescriptionFromContent: generateDescriptionFromContent,
        autoGenerateDescription: autoGenerateDescription,
        updateDescriptionCounter: updateDescriptionCounter,
        showDescriptionConfirm: showDescriptionConfirm
    };

    global.ArticleDescriptionHelper = api;

    // 兼容模板中已有的 onclick="autoGenerateDescription()" /
    // updateDescriptionCounter() 调用，不需要改 HTML。
    global.autoGenerateDescription = autoGenerateDescription;
    global.updateDescriptionCounter = updateDescriptionCounter;

    // ==================================================================
    // 8. 自动绑定描述输入框的输入事件（保证多处引用时不重复计数逻辑）
    // ==================================================================
    function bindCounterEvents() {
        var descInput = document.getElementById('description');
        if (!descInput) return;

        var events = ['input', 'change', 'keyup', 'paste'];
        for (var i = 0; i < events.length; i++) {
            descInput.addEventListener(events[i], updateDescriptionCounter, false);
        }

        updateDescriptionCounter();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', bindCounterEvents, false);
    } else {
        bindCounterEvents();
    }
})(window);
